async function adjustStockPwa(id){
 const products=await all("products"),product=products.find(x=>x.id===Number(id));
 if(!product)throw Error("کالا پیدا نشد");
 const raw=prompt("مقدار اصلاح به کیلوگرم را وارد کنید. عدد مثبت = افزایش، عدد منفی = کاهش", "10");
 if(raw===null)return;
 const delta=Number(String(raw).replace(",","."));
 if(!Number.isFinite(delta)||Math.abs(delta)<0.000001)throw Error("مقدار اصلاح معتبر نیست");
 let adjustmentValue=0,debitCode="",creditCode="";
 if(delta>0){
  const costRaw=prompt("بهای هر کیلو برای افزایش موجودی (ریال)",String(Math.round(Number(product.avg)||0)));
  if(costRaw===null)return;
  const cost=Number(costRaw);
  if(!Number.isSafeInteger(cost)||cost<=0)throw Error("بهای هر کیلو باید عدد صحیح مثبت باشد");
  adjustmentValue=Math.round(delta*cost);
  if(!Number.isSafeInteger(adjustmentValue)||adjustmentValue<=0)throw Error("ارزش اصلاح خارج از محدوده مجاز است");
  product.value=Number(product.value||0)+adjustmentValue;product.stock=Number(product.stock||0)+delta;product.avg=product.value/product.stock;
  debitCode="1301";creditCode="4201";
 }else{
  const qty=-delta;
  if(Number(product.stock||0)+1e-9<qty)throw Error("موجودی برای این کاهش کافی نیست");
  if(!(Number(product.avg)>0))throw Error("ابتدا بهای موجودی کالا را مشخص کنید");
  adjustmentValue=Math.round(qty*Number(product.avg));
  if(!Number.isSafeInteger(adjustmentValue)||adjustmentValue<=0||adjustmentValue>Number(product.value||0)+1)throw Error("ارزش کسری موجودی معتبر نیست");
  product.stock=Number(product.stock||0)-qty;product.value=Math.max(0,Number(product.value||0)-adjustmentValue);
  product.avg=product.stock>0?product.value/product.stock:0;
  debitCode="5201";creditCode="1301";
 }
 await ensureBaseAccounts();
 const accounts=await all("accounts"),byCode=new Map(accounts.map(x=>[x.code,x]));
 const debit=byCode.get(debitCode),credit=byCode.get(creditCode);
 if(!debit||!credit)throw Error("حساب اصلاح موجودی تعریف نشده است");
 const now=Date.now(),number="ADJ-"+now;
 const adjustment={productId:product.id,productName:product.name,deltaKg:delta,valueRial:adjustmentValue,date:now,number};
 await postVoucherAtomic([["products",product],["stockAdjustments",adjustment]],{number,date:now,description:"اصلاح موجودی "+product.name,reference:"STOCK_ADJUSTMENT:"+product.id+":"+now},[
  {accountCode:debitCode,debitRial:adjustmentValue,creditRial:0,description:"اصلاح موجودی"},
  {accountCode:creditCode,debitRial:0,creditRial:adjustmentValue,description:"اصلاح موجودی"}
 ]);
 toast("اصلاح موجودی و سند حسابداری ثبت شد");await render();
}
async function receiveImportShipment(id){
 const shipments=await all("importShipments"),shipment=shipments.find(x=>Number(x.id)===Number(id));
 if(!shipment)throw Error("محموله پیدا نشد");
 if(shipment.receivedAt)throw Error("این محموله قبلاً رسید انبار شده است");
 if(shipment.status!=="رسیده")throw Error("ابتدا وضعیت محموله را به «رسیده» تغییر دهید");
 const [products,parties,warehouses,stockRows,lots,foreignPayables]=await Promise.all([all("products"),all("parties"),all("warehouses"),all("warehouseStock"),all("inventoryLots"),all("foreignPayables")]);
 const product=products.find(x=>Number(x.id)===Number(shipment.productId)),party=parties.find(x=>Number(x.id)===Number(shipment.supplierId)),warehouse=warehouses.find(x=>Number(x.id)===Number(shipment.warehouseId));
 if(!product||!party||!warehouse)throw Error("کالا، تأمین‌کننده یا انبار مقصد محموله پیدا نشد");
 const costs=calculateImportShipmentCost({currency:shipment.currency,fx:shipment.fx,weight:shipment.weight,goods:shipment.goods,freight:shipment.freight,customs:shipment.customs,other:shipment.other});
 const currentStock=Number(product.stock||0),currentValue=Number(product.value||0);
 if(!Number.isFinite(currentStock)||currentStock<0||!Number.isSafeInteger(currentValue)||currentValue<0)throw Error("موجودی کل کالا برای رسید معتبر نیست");
 const nextStock=currentStock+Number(shipment.weight),nextValue=currentValue+costs.totalCost;
 if(!Number.isFinite(nextStock)||!Number.isSafeInteger(nextValue))throw Error("موجودی یا ارزش کل کالا از محدوده مجاز خارج می‌شود");
 const movement=calculateWarehouseStockMovement({product,warehouseId:warehouse.id,warehouseRows:stockRows.filter(x=>Number(x.productId)===Number(product.id)),quantity:Number(shipment.weight),direction:"PURCHASE",lineTotal:costs.totalCost});
 product.stock=nextStock;product.value=nextValue;product.avg=nextStock>0?nextValue/nextStock:0;
 const ancillary=costs.totalCost-costs.goodsRial,now=Date.now(),reference="IMPORT-RECEIPT:"+shipment.number;
 shipment.goodsRial=costs.goodsRial;shipment.totalCost=costs.totalCost;shipment.unitCost=costs.unitCost;shipment.status="رسید انبار شده";shipment.receivedAt=now;shipment.receivedVoucherNumber="IMP-"+now;
 const linkedPayable=foreignPayables.find(x=>Number(x.sourceShipmentId)===Number(shipment.id));if(linkedPayable)linkedPayable.shipmentReceivedAt=now;
 const lot=planLotReceipt({productId:product.id,productName:product.name,warehouseId:warehouse.id,sourceType:"IMPORT_SHIPMENT",sourceId:shipment.id,sourceNumber:shipment.number,container:shipment.container,supplierId:party.id,supplierName:party.name,quantity:Number(shipment.weight),totalCost:costs.totalCost,receivedAt:now});
 if(lots.some(x=>x.id===lot.id))throw Error("برای این محموله قبلاً بچ موجودی ثبت شده است");
 party.balance=Number(party.balance||0)-costs.goodsRial;
 const ledger={partyId:party.id,date:now,debitRial:0,creditRial:costs.goodsRial,description:"ثبت بدهی خرید محموله "+shipment.number,referenceId:reference};
 const journal=[{accountCode:"1301",debitRial:costs.totalCost,creditRial:0,description:"ورود موجودی محموله "+shipment.number}];
 if(costs.goodsRial>0)journal.push({accountCode:"2101",debitRial:0,creditRial:costs.goodsRial,description:"بدهی بهای کالا به تأمین‌کننده"});
 if(ancillary>0)journal.push({accountCode:"2102",debitRial:0,creditRial:ancillary,description:"هزینه‌های جانبی واردات پرداختنی"});
 if(journal.reduce((n,x)=>n+x.debitRial,0)!==journal.reduce((n,x)=>n+x.creditRial,0))throw Error("سند رسید محموله تراز نیست");
 await ensureBaseAccounts();
 await postVoucherAtomic([["products",product],["warehouseStock",movement.record],["importShipments",shipment],["inventoryLots",lot],...(linkedPayable?[["foreignPayables",linkedPayable]]:[]),["parties",party],["partyLedger",ledger]],{number:shipment.receivedVoucherNumber,date:now,description:"رسید انبار محموله "+shipment.number,reference},journal);
 toast("محموله رسید انبار شد؛ بهای تمام‌شده به موجودی کالا اضافه شد");await render();
}
async function importBankStatementCsv(file,bankName){
 if(!file)throw Error("فایل CSV انتخاب نشده است");
 const bank=String(bankName||"").trim();if(!bank)throw Error("نام بانک را وارد کنید");
 const existing=await all("bankStatements");
 if(existing.some(x=>x.bank===bank&&x.fileName===file.name&&Number(x.fileSize)===Number(file.size)&&Number(x.lastModified)===Number(file.lastModified)))throw Error("این فایل صورت‌حساب قبلاً وارد شده است");
 const parsed=parseBankCsv(await file.text(),bank);
 const statementId=await new Promise((resolve,reject)=>{const tx=db.transaction(["bankStatements","bankStatementLines","auditLog"],"readwrite"),request=tx.objectStore("bankStatements").add({bank,fileName:file.name,fileSize:file.size,lastModified:file.lastModified,importedAt:Date.now(),rowCount:parsed.length});let id=null;request.onsuccess=()=>{id=request.result;for(const line of parsed)tx.objectStore("bankStatementLines").add({...line,statementId:id});tx.objectStore("auditLog").add({action:"ورود صورت‌حساب بانکی",store:"bankStatements",recordId:id,at:Date.now(),summary:file.name})};request.onerror=()=>{try{tx.abort()}catch(_){}};tx.oncomplete=()=>resolve(id);tx.onerror=()=>reject(tx.error||new Error("ورود صورت‌حساب ناموفق بود"));tx.onabort=()=>reject(tx.error||new Error("ورود صورت‌حساب لغو شد"))});
 await autoReconcileBankStatementLines();
 return parsed.length;
}
async function autoReconcileBankStatementLines(){
 const [lines,treasury]=await Promise.all([all("bankStatementLines"),all("treasury")]);
 const updated=autoMatchBankLines(lines,treasury,3);
 await putMany(updated.map(line=>["bankStatementLines",line]));
 return updated.filter(x=>x.status==="MATCHED").length;
}
async function matchBankStatementLine(lineId,treasuryId){
 const [lines,treasury]=await Promise.all([all("bankStatementLines"),all("treasury")]);
 const line=lines.find(x=>Number(x.id)===Number(lineId)),row=treasury.find(x=>Number(x.id)===Number(treasuryId));
 if(!line)throw Error("ردیف صورت‌حساب پیدا نشد");
 const matchedIds=lines.filter(x=>x.status==="MATCHED"&&Number(x.id)!==Number(line.id)).map(x=>x.matchedTreasuryId);
 validateBankManualMatch(line,row,matchedIds);
 line.status="MATCHED";line.matchedTreasuryId=row.id;line.candidateTreasuryIds=[];line.matchedAt=Date.now();
 await put("bankStatementLines",line);
}
