function partyStatementRows(party,ledger){
 const rows=ledger.filter(r=>Number(r.partyId)===Number(party.id)).sort((a,b)=>Number(a.date||0)-Number(b.date||0));
 const movement=rows.reduce((n,r)=>n+Number(r.debitRial||0)-Number(r.creditRial||0),0);
 let balance=Number(party.balance||0)-movement;
 return rows.map(r=>{balance+=Number(r.debitRial||0)-Number(r.creditRial||0);return '<tr><td>'+date(r.date)+'</td><td>'+h(r.description)+'</td><td>'+money(r.debitRial||0)+'</td><td>'+money(r.creditRial||0)+'</td><td>'+money(balance)+'</td></tr>'}).join('')||'<tr><td colspan="5">گردشی برای این شخص ثبت نشده است</td></tr>';
}
