async function reverseForeignPayablePaymentPwa(id){
 const [payments,payables,parties,treasury]=await Promise.all([all("foreignPayablePayments"),all("foreignPayables"),all("parties"),all("treasury")]);
 const payment=payments.find(x=>Number(x.id)===Number(id));
 if(!payment||payment.status==="REVERSED")throw Error("پرداخت ارزی پیدا نشد یا قبلاً برگشت خورده است");
 const payable=payables.find(x=>Number(x.id)===Number(payment.payableId)),party=parties.find(x=>Number(x.id)===Number(payment.supplierId));
 const originalTreasury=treasury.find(x=>x.reference===payment.reference);
 if(!payable||!party||!originalTreasury)throw Error("تعهد، تأمین‌کننده یا گردش خزانه پرداخت پیدا نشد");
 const now=Date.now(),plan=HolooForeignPayables.planForeignPayableReversal({payable,payment,date:now}),reference="FXPAY-REV:"+payment.id;
 if(treasury.some(x=>x.reference===reference))throw Error("سند برگشت این پرداخت قبلاً ثبت شده است");
 const cashAccount=payment.method==="بانک"?"1102":"1101",journal=[{accountCode:cashAccount,debitRial:plan.settlementRial,creditRial:0,description:"برگشت وجه پرداخت ارزی "+payment.sourceNumber},{accountCode:"2101",debitRial:0,creditRial:plan.bookedRial,description:"برگشت بدهی ارزی "+payment.sourceNumber}];
 if(plan.fxGainRial>0)journal.push({accountCode:"4301",debitRial:plan.fxGainRial,creditRial:0,description:"برگشت سود تسعیر پرداخت "+payment.sourceNumber});
 if(plan.fxLossRial>0)journal.push({accountCode:"5501",debitRial:0,creditRial:plan.fxLossRial,description:"برگشت زیان تسعیر پرداخت "+payment.sourceNumber});
 party.balance=Number(party.balance||0)-plan.bookedRial;
 const originalTreasuryUpdated={...originalTreasury,status:"REVERSED",reversedAt:now};
 const reversalTreasury={kind:"RECEIPT",method:payment.method,partyId:party.id,partyName:party.name,amount:plan.settlementRial,currency:payment.currency,foreignAmountMinor:payment.amountMinor,fxRateRialPerUnit:payment.fxRateRialPerUnit,date:now,note:"برگشت پرداخت ارزی "+payment.sourceNumber,reference,foreignPayableId:payable.id,reversalOf:payment.reference};
 const movement={partyId:party.id,date:now,debitRial:0,creditRial:plan.bookedRial,description:"برگشت پرداخت تعهد ارزی "+payment.sourceNumber,referenceId:reference};
 await ensureBaseAccounts();
 await postVoucherAtomic([["foreignPayables",plan.updated],["foreignPayablePayments",plan.reversedPayment],["treasury",originalTreasuryUpdated],["treasury",reversalTreasury],["parties",party],["partyLedger",movement]],{number:"FXPR-"+now,date:now,description:"برگشت پرداخت تعهد ارزی "+payment.sourceNumber,reference},journal);
}
async function exportBackup(prefix="holloo-backup"){
 const records={},counts={};
 for(const store of stores){records[store]=await all(store);counts[store]=records[store].length}
 const data={app:"HOLLOO PRO+ PWA",version:2,schemaVersion:DB_VERSION,exportedAt:new Date().toISOString(),storeNames:[...stores],counts,records};
 const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");
 a.href=url;a.download=prefix+"-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
 return {counts,total:Object.values(counts).reduce((sum,n)=>sum+n,0)};
}
async function restoreBackup(file){
 if(!file||!file.size||file.size>50*1024*1024)throw Error("فایل پشتیبان خالی است یا از سقف ۵۰ مگابایت بزرگ‌تر است");
 let data;try{data=JSON.parse(await file.text())}catch(_){throw Error("محتوای فایل JSON معتبر نیست")}
 if(data.app!=="HOLLOO PRO+ PWA"||![1,2].includes(Number(data.version))||!data.records||typeof data.records!=="object"||Array.isArray(data.records))throw Error("فایل پشتیبان معتبر یا سازگار نیست");
 const unknown=Object.keys(data.records).filter(name=>!stores.includes(name));if(unknown.length)throw Error("فایل شامل بخش ناشناخته است: "+unknown.join("، "));
 const counts={};let total=0;
 for(const store of stores){
  const rows=data.records[store]??[];
  if(!Array.isArray(rows))throw Error("ساختار اطلاعات «"+store+"» در فایل پشتیبان معتبر نیست");
  const ids=new Set();
  for(const row of rows){
   if(!row||typeof row!=="object"||Array.isArray(row)||!("id" in row)||(typeof row.id!=="string"&&(!Number.isSafeInteger(row.id)||row.id<0))||(typeof row.id==="string"&&!row.id.trim()))throw Error("شناسه یکی از رکوردهای «"+store+"» معتبر نیست");
   const key=String(row.id);if(ids.has(key))throw Error("شناسه تکراری در بخش «"+store+"»: "+key);ids.add(key);
  }
  counts[store]=rows.length;total+=rows.length;
 }
 if(data.version===2&&(!Array.isArray(data.storeNames)||stores.some(name=>!data.storeNames.includes(name))))throw Error("فایل پشتیبان نسخه جدید ناقص است");
 if(!confirm("بازیابی "+total+" رکورد از فایل پشتیبان انجام شود؟ تمام اطلاعات فعلی جایگزین می‌شود. پیش از جایگزینی، یک نسخه پشتیبان خودکار از اطلاعات فعلی دانلود خواهد شد."))return;
 await exportBackup("holloo-before-restore");
 const tx=db.transaction(stores,"readwrite");
 for(const store of stores){const objectStore=tx.objectStore(store);objectStore.clear();for(const row of data.records[store]||[])objectStore.put(row)}
 await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error("بازیابی ناموفق بود"));tx.onabort=()=>reject(tx.error||new Error("بازیابی لغو شد"))});
 toast("بازیابی "+total+" رکورد انجام شد؛ پشتیبان قبلی نیز دانلود شد");await render()
}
$("#exportBtn").onclick=exportBackup;$("#importBtn").onclick=()=>$("#restoreFile").click();$("#restoreFile").onchange=e=>{if(e.target.files[0])restoreBackup(e.target.files[0]).catch(x=>toast(x.message))};$("#unitBtn").onclick=()=>{showToman=!showToman;$("#unitBtn").textContent=moneyUnit();render()};$("#closeModal").onclick=$("#cancelModal").onclick=()=>$("#modal").hidden=true;$("#modal").onclick=e=>{if(e.target.id==="modal")$("#modal").hidden=true};
(async()=>{const stage=s=>{window.__HOLLOO_STAGE__=s;const el=$("#main");if(el&&el.querySelector(".loading"))el.querySelector(".loading").textContent=s};stage("۱ از ۴: باز کردن پایگاه داده");db=await openDB();stage("۲ از ۴: آماده‌سازی حساب‌ها");await ensureBaseAccounts();stage("۳ از ۴: ساخت منو");nav();stage("۴ از ۴: خواندن اطلاعات و نمایش داشبورد");await render();window.__HOLLOO_READY__=true;window.__HOLLOO_STAGE__="آماده";if("serviceWorker"in navigator)navigator.serviceWorker.register("./sw.js?v=aging-1").catch(()=>{})})().catch(e=>{window.__HOLLOO_STAGE__="خطا: "+(e&&e.message?e.message:String(e));const main=$("#main");if(main)main.innerHTML='<div class="card"><h2>خطا در راه‌اندازی دفتر</h2><p>'+h(e&&e.message?e.message:String(e))+'</p><p>مرحله: '+h(window.__HOLLOO_STAGE__)+'</p></div>';console.error("HOLLOO_STARTUP",e)});
